const Comparable = (Base) => class extends Base {
  isGreaterThan(other) { return this.compare(other) > 0; }
  isLessThan(other) { return this.compare(other) < 0; }
};

class Money extends Comparable(class {}) {
  constructor(cents) { super(); this.cents = cents; }
  compare(other) { return this.cents - other.cents; }
}
